import networkx as nx

def cluster_states(grid, start, goal):
    # Create a graph with grid coordinates as nodes
    G = nx.Graph()

    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] != "X":
                G.add_node((i, j))

                # Add edges between adjacent cells
                if i > 0 and grid[i-1][j] != "X" and ((i-1, j) not in G.nodes()):
                    G.add_edge((i, j), (i-1, j))
                if i < len(grid)-1 and grid[i+1][j] != "X" and ((i+1, j) not in G.nodes()):
                    G.add_edge((i, j), (i+1, j))
                if j > 0 and grid[i][j-1] != "X" and ((i, j-1) not in G.nodes()):
                    G.add_edge((i, j), (i, j-1))
                if j < len(grid[i])-1 and grid[i][j+1] != "X" and ((i, j+1) not in G.nodes()):
                    G.add_edge((i, j), (i, j+1))

    # Find all connected components
    components = [list(c) for c in nx.connected_components(G)]

    clusters = {}

    for component in components:
        cluster_center = None
        min_distance = float('inf')

        for node in component:
            distance_to_goal = abs(node[0] - goal//len(grid)) + abs(node[1] - goal%len(grid))

            if distance_to_goal < min_distance:
                min_distance = distance_to_goal
                cluster_center = node

        cluster = set(component)

        for other_component in components:
            if component == other_component:
                continue

            for node in other_component:
                # Check if a state is equivalent to the current one by rotating or reflecting it
                for _ in range(4):
                    rotated_node = (cluster_center[0] - node[0], cluster_center[1] - node[1])

                    if (rotated_node[0]**2 + rotated_node[1]**2) <= 5**2:
                        equivalent_nodes = set()

                        for n in component:
                            rotated_n = (cluster_center[0] - n[0], cluster_center[1] - n[1])

                            if ((rotated_n[0]-rotated_node[0])**2 + (rotated_n[1]-rotated_node[1])**2) <= 5**2 and (rotated_n not in equivalent_nodes):
                                equivalent_nodes.add(n)

                        for m in other_component:
                            rotated_m = (cluster_center[0] - m[0], cluster_center[1] - m[1])

                            if ((rotated_m[0]-rotated_node[0])**2 + (rotated_m[1]-rotated_node[1])**2) <= 5**2 and (m not in equivalent_nodes):
                                equivalent_nodes.add(m)

                        if len(equivalent_nodes & cluster) > 0:
                            cluster |= set(other_component)

                    # Check reflection
                    reflected_node = (-cluster_center[0] - node[0], cluster_center[1] - node[1])

                    if (reflected_node[0]**2 + reflected_node[1]**2) <= 5**2:
                        equivalent_nodes = set()

                        for n in component:
                            reflected_n = (-cluster_center[0] - n[0], cluster_center[1] - n[1])

                            if ((reflected_n[0]-reflected_node[0])**2 + (reflected_n[1]-reflected_node[1])**2) <= 5**2 and (reflected_n not in equivalent_nodes):
                                equivalent_nodes.add(n)

                        for m in other_component:
                            reflected_m = (-cluster_center[0] - m[0], cluster_center[1] - m[1])

                            if ((reflected_m[0]-reflected_node[0])**2 + (reflected_m[1]-reflected_node[1])**2) <= 5**2 and (m not in equivalent_nodes):
                                equivalent_nodes.add(m)

                        if len(equivalent_nodes & cluster) > 0:
                            cluster |= set(other_component)

        clusters[tuple(component)] = tuple(sorted(cluster))

    return clusters

