from typing import List, Tuple
import numpy as np


class State:
    def __init__(self, value: int, x: int, y: int):
        self.value = value
        self.x = x
        self.y = y

    def __repr__(self):
        return f"State({self.value}, {self.x}, {self.y})"


class Grid:
    def __init__(self, grid: List[List[str]]):
        self.grid = np.array([[int(cell) if cell != "X" else float("inf") for cell in row] for row in grid])
        self.rows, self.cols = self.grid.shape
        self.start_value = None

    @property
    def start(self):
        return State(0, 0, 0)


def cluster_states(grid: Grid) -> List[List[State]]:
    goal_state = State(grid["goal"], grid["grid"].shape[1] - 1, grid["grid"].shape[0] - 1)
    abstract_states = [[[] for _ in range(4)] for __ in range(4)]
    visited = set()

    def cluster(state: State):
        if state.value == float("inf"):
            return
        visited.add((state.x, state.y))
        queue = [state]
        while queue:
            current_state = queue.pop(0)
            neighbors = get_neighbors(grid, current_state)

            for neighbor in neighbors:
                if (neighbor.x, neighbor.y) not in visited and abs(neighbor.value - goal_state.value) <= abs(current_state.value - goal_state.value):
                    cluster(neighbor)
                    abstract_states[0][1].append((current_state.x, current_state.y))
                    abstract_states[0][2].append((neighbor.x, neighbor.y))

            if (current_state.x, current_state.y) not in visited:
                visited.add((current_state.x, current_state.y))
                queue.extend(neighbors)

    cluster(grid.start)

    for x in range(1, grid.rows):
        for y in range(4):
            abstract_states[x][y].extend([(x, y)])

    return [[State(cell[0], cell[1], 0) if cell else State(float("inf"), -1, -1) for cell in cluster] for cluster in abstract_states]


def get_neighbors(grid: Grid, state: State) -> List[State]:
    neighbors = []
    x, y = state.x, state.y
    possible_actions = [(x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)]
    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        new_x, new_y = x + dx, y + dy
        if 0 <= new_x < grid.rows and 0 <= new_y < grid.cols and (new_x, new_y) not in [(x, y) for x, y in possible_actions]:
            neighbors.append(State(grid.grid[new_x, new_y], new_x, new_y))

    return neighbors


